// PLAN:
// 1. Setup & Theming: Inject NXT brand tokens as CSS variables. Load Bebas Neue, Archivo, JetBrains Mono.
// 2. State Management: Centralized state object holding `currentScreen`, `constraints`, `zones`, `estimates`, `chatHistory`, `isProcessing`.
// 3. Components:
//    - App: Root container, manages state transitions and layout shell.
//    - Header: NXT branding and global actions.
//    - Screen1_Dashboard: Video upload dropzone with hover/active states.
//    - Screen2_Processing: Simulated video analysis with scanning mesh animation. Triggers `ai_vision_constraints`.
//    - Screen3_Workspace: Main CAD-lite interface. SVG map for spatial data, Chat panel for interaction.
//    - Screen4_WorkspaceZoned: Same as S3 but renders the newly placed zone and a FAB for estimates.
//    - Screen5_EstimatePanel: Slides in an itemized BOM table, dimming the map.
// 4. AI Integrations (Real Fetch Calls):
//    - `ai_vision_constraints`: Gemini 3.1 Pro. Prompts for structured JSON of site constraints (slope, shade) simulating vision extraction.
//    - `ai_spatial_chat`: Claude Opus 4.6. Takes user prompt + constraints, returns new zone coordinates and conversational response.
//    - `ai_material_estimate`: OpenAI GPT-5.5. Takes zone data + constraints, returns itemized material list and costs.
// 5. Micro-interactions: Framer motion for dropzone scaling, map polygon rendering, and panel slide-ins.

const SEED_PROJECT = {
  id: 'proj_882',
  client_name: 'Chen Residence',
  address: '142 Oak Lane',
  status: 'In Progress',
};

const FALLBACK_CONSTRAINTS = [
  { id: 'const_01', type: 'slope', polygon_coordinates: [[10, 10], [90, 10], [90, 30], [10, 30]], value: '5%', description: '5% grade sloping North to South' },
  { id: 'const_02', type: 'shade', polygon_coordinates: [[60, 60], [95, 60], [95, 95], [60, 95]], value: 'deep_shade', description: 'Deep shade under mature Oak tree' },
  { id: 'const_03', type: 'structure', polygon_coordinates: [[20, 70], [40, 70], [40, 90], [20, 90]], value: 'retaining_wall', description: 'Existing 2ft concrete retaining wall' }
];

const FALLBACK_ZONE = {
  id: 'zone_99',
  name: 'Flagstone Patio',
  material_type: 'colorado_red_flagstone',
  area_sqft: 225,
  coordinates: [[15, 35], [45, 35], [45, 65], [15, 65]],
  ai_rationale: 'Placed in SW corner to maximize sun exposure; overlaps 5% slope constraint requiring grading.'
};

const FALLBACK_ESTIMATE = [
  { item: 'Colorado Red Flagstone', quantity: 250, unit: 'sqft', unit_cost: 8.50, total: 2125.00 },
  { item: 'Class II Base Rock', quantity: 4.5, unit: 'tons', unit_cost: 45.00, total: 202.50 },
  { item: 'Grading Labor (Machine)', quantity: 4, unit: 'hours', unit_cost: 125.00, total: 500.00 }
];

// --- Helpers ---
const parseAIJSON = (text) => {
  try {
    const cleaned = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    console.error("Failed to parse AI JSON:", text);
    return null;
  }
};

// --- Components ---

const Header = ({ onReset }) => (
  <header style={{
    height: '64px',
    borderBottom: '1px solid var(--border)',
    display: 'flex',
    alignItems: 'center',
    padding: '0 24px',
    backgroundColor: 'var(--background)',
    justifyContent: 'space-between',
    position: 'relative',
    zIndex: 10
  }}>
    <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
      <div style={{ 
        fontFamily: 'var(--font-display)', 
        fontSize: '24px', 
        letterSpacing: '0.02em',
        color: 'var(--text-primary)',
        cursor: 'pointer'
      }} onClick={onReset}>
        NXT <span style={{ color: 'var(--emphasis)' }}>TERRAFLOW</span>
      </div>
      <div style={{ width: '1px', height: '24px', backgroundColor: 'var(--border)' }} />
      <div style={{ fontFamily: 'var(--font-body)', fontSize: '14px', color: 'var(--text-secondary)' }}>
        {SEED_PROJECT.client_name} — {SEED_PROJECT.address}
      </div>
    </div>
    <div style={{ display: 'flex', gap: '16px' }}>
      <button className="btn-ghost"><lucide.Settings size={16} /> Settings</button>
    </div>
  </header>
);

const Screen1_Dashboard = ({ onUpload }) => {
  const [isDragging, setIsDragging] = useState(false);

  return (
    <div style={{ padding: '48px', maxWidth: '1000px', margin: '0 auto' }}>
      <h1 style={{ fontFamily: 'var(--font-display)', fontSize: '48px', marginBottom: '8px' }}>Site Analysis</h1>
      <p style={{ color: 'var(--text-secondary)', marginBottom: '32px' }}>Upload raw site walkthrough footage to extract physical constraints and begin co-design.</p>

      <motion.div
        onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => { e.preventDefault(); setIsDragging(false); onUpload(); }}
        onClick={onUpload}
        animate={{
          scale: isDragging ? 0.98 : 1,
          borderColor: isDragging ? 'var(--emphasis)' : 'var(--border)',
          backgroundColor: isDragging ? 'var(--surface)' : 'var(--background)'
        }}
        style={{
          border: '2px dashed var(--border)',
          borderRadius: 'var(--radius)',
          height: '300px',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          cursor: 'pointer',
          transition: 'all 0.2s ease'
        }}
      >
        <div style={{ 
          width: '64px', height: '64px', 
          borderRadius: '50%', 
          backgroundColor: 'var(--surface)', 
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          marginBottom: '16px',
          color: isDragging ? 'var(--emphasis)' : 'var(--text-secondary)'
        }}>
          <lucide.UploadCloud size={32} />
        </div>
        <h3 style={{ fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: '16px', marginBottom: '4px' }}>
          Drag & Drop Site Walk Video
        </h3>
        <p style={{ color: 'var(--text-tertiary)', fontSize: '14px' }}>MP4 or MOV up to 500MB</p>
      </motion.div>

      <div style={{ marginTop: '48px' }}>
        <h4 style={{ fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: '12px', textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', marginBottom: '16px' }}>
          Recent Projects
        </h4>
        <div style={{ border: '1px solid var(--border)', borderRadius: 'var(--radius)' }}>
          {[1, 2, 3].map((i) => (
            <div key={i} style={{ 
              padding: '16px 24px', 
              borderBottom: i !== 3 ? '1px solid var(--border)' : 'none',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}>
              <div>
                <div style={{ fontWeight: 700 }}>Smith Residence</div>
                <div style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>Analyzed 2 days ago</div>
              </div>
              <button className="btn-ghost">View <lucide.ArrowRight size={16} /></button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const Screen2_Processing = ({ onComplete }) => {
  const [status, setStatus] = useState('Initializing vision models...');

  useEffect(() => {
    const statuses = [
      'Extracting grade percentages...',
      'Mapping shade zones...',
      'Identifying existing structures...',
      'Synthesizing spatial constraints...'
    ];
    let i = 0;
    const interval = setInterval(() => {
      i++;
      if (i < statuses.length) setStatus(statuses[i]);
    }, 1500);

    // Simulate the AI call taking time
    const runAI = async () => {
      try {
        const res = await fetch('/api/ai/gemini-compat', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
          body: JSON.stringify({
            model: 'gemini-3.1-pro-preview',
            messages: [
              { role: 'system', content: 'You are a landscape architect AI. Return ONLY valid JSON representing site constraints extracted from a video. Format: { "constraints": [ { "id": "string", "type": "slope|shade|structure", "polygon_coordinates": [[x,y]... 0-100 scale], "value": "string", "description": "string" } ] }' },
              { role: 'user', content: 'Extract constraints for a backyard with a 5% slope, a large shade tree, and a small retaining wall.' }
            ],
            temperature: 0.1,
            max_tokens: 800,
          }),
        });
        const data = await res.json();
        const parsed = parseAIJSON(data?.choices?.[0]?.message?.content || '');
        clearInterval(interval);
        onComplete(parsed?.constraints || FALLBACK_CONSTRAINTS);
      } catch (e) {
        clearInterval(interval);
        onComplete(FALLBACK_CONSTRAINTS);
      }
    };
    runAI();
    return () => clearInterval(interval);
  }, [onComplete]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: 'calc(100vh - 64px)', backgroundColor: 'var(--surface)' }}>
      <div style={{ width: '600px', height: '400px', backgroundColor: '#0D0D0D', position: 'relative', overflow: 'hidden', borderRadius: 'var(--radius)', border: '1px solid var(--border)' }}>
        {/* Simulated Video Background */}
        <div style={{ position: 'absolute', inset: 0, opacity: 0.3, backgroundImage: 'radial-gradient(circle at 50% 50%, #115054 0%, #0D0D0D 100%)' }} />

        {/* Scanning Mesh Animation */}
        <motion.div
          animate={{ top: ['-10%', '110%'] }}
          transition={{ duration: 3, repeat: Infinity, ease: "linear" }}
          style={{
            position: 'absolute',
            left: 0, right: 0, height: '2px',
            backgroundColor: 'var(--emphasis)',
            boxShadow: '0 0 20px var(--emphasis)'
          }}
        />
        <div style={{ position: 'absolute', inset: 0, backgroundImage: 'linear-gradient(0deg, transparent 24%, rgba(255, 255, 255, .05) 25%, rgba(255, 255, 255, .05) 26%, transparent 27%, transparent 74%, rgba(255, 255, 255, .05) 75%, rgba(255, 255, 255, .05) 76%, transparent 77%, transparent), linear-gradient(90deg, transparent 24%, rgba(255, 255, 255, .05) 25%, rgba(255, 255, 255, .05) 26%, transparent 27%, transparent 74%, rgba(255, 255, 255, .05) 75%, rgba(255, 255, 255, .05) 76%, transparent 77%, transparent)', backgroundSize: '50px 50px' }} />
      </div>

      <div style={{ marginTop: '32px', display: 'flex', alignItems: 'center', gap: '16px' }}>
        <motion.div animate={{ rotate: 360 }} transition={{ duration: 2, repeat: Infinity, ease: "linear" }}>
          <lucide.Loader2 size={24} color="var(--emphasis)" />
        </motion.div>
        <div style={{ fontFamily: 'var(--font-mono)', fontSize: '14px', color: 'var(--text-secondary)' }}>
          {status}
        </div>
      </div>
    </div>
  );
};

const MapViewport = ({ constraints, zone, isEstimating }) => {
  const toSvgCoords = (coords) => coords.map(c => `${c[0]},${c[1]}`).join(' ');

  return (
    <div style={{ 
      flex: 1, 
      backgroundColor: 'var(--surface)', 
      position: 'relative',
      overflow: 'hidden',
      borderRight: '1px solid var(--border)',
      transition: 'all 0.5s ease',
      opacity: isEstimating ? 0.5 : 1
    }}>
      {/* Grid Background */}
      <div style={{ position: 'absolute', inset: 0, backgroundImage: 'linear-gradient(var(--border) 1px, transparent 1px), linear-gradient(90deg, var(--border) 1px, transparent 1px)', backgroundSize: '20px 20px', opacity: 0.5 }} />

      <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none" style={{ position: 'absolute', inset: 0 }}>
        {/* Constraints */}
        {constraints.map(c => {
          let fill = 'rgba(0,0,0,0.05)';
          let stroke = 'var(--border)';
          if (c.type === 'shade') { fill = 'rgba(17, 80, 84, 0.2)'; stroke = 'var(--teal)'; }
          if (c.type === 'slope') { fill = 'rgba(204, 102, 68, 0.1)'; stroke = 'var(--rust)'; }

          return (
            <g key={c.id}>
              <polygon 
                points={toSvgCoords(c.polygon_coordinates)} 
                fill={fill} 
                stroke={stroke} 
                strokeWidth="0.5"
                strokeDasharray={c.type === 'slope' ? "1,1" : "none"}
              />
              <text x={c.polygon_coordinates[0][0] + 2} y={c.polygon_coordinates[0][1] + 5} fontSize="2" fill="var(--text-secondary)" fontFamily="var(--font-mono)">
                {c.type.toUpperCase()}: {c.value}
              </text>
            </g>
          );
        })}

        {/* Zone */}
        <AnimatePresence>
          {zone && (
            <motion.g
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.5, ease: "easeOut" }}
            >
              <polygon 
                points={toSvgCoords(zone.coordinates)} 
                fill="rgba(184, 184, 0, 0.3)" 
                stroke="var(--emphasis)" 
                strokeWidth="1"
              />
              <text x={zone.coordinates[0][0] + 2} y={zone.coordinates[0][1] + 5} fontSize="3" fill="var(--text-primary)" fontFamily="var(--font-body)" fontWeight="bold">
                {zone.name}
              </text>
              <text x={zone.coordinates[0][0] + 2} y={zone.coordinates[0][1] + 8} fontSize="2" fill="var(--text-secondary)" fontFamily="var(--font-mono)">
                {zone.area_sqft} SQFT
              </text>
            </motion.g>
          )}
        </AnimatePresence>
      </svg>

      {/* Layer Toggles */}
      <div style={{ position: 'absolute', bottom: '24px', left: '24px', display: 'flex', gap: '8px', backgroundColor: 'var(--background)', padding: '8px', border: '1px solid var(--border)', borderRadius: 'var(--radius)' }}>
        <div style={{ fontSize: '12px', fontWeight: 700, padding: '4px 8px', backgroundColor: 'var(--surface)', border: '1px solid var(--border)' }}>LAYERS</div>
        <div style={{ fontSize: '12px', padding: '4px 8px', display: 'flex', alignItems: 'center', gap: '4px' }}><div style={{width:8,height:8,backgroundColor:'var(--teal)'}}/> Shade</div>
        <div style={{ fontSize: '12px', padding: '4px 8px', display: 'flex', alignItems: 'center', gap: '4px' }}><div style={{width:8,height:8,backgroundColor:'var(--rust)'}}/> Topography</div>
      </div>
    </div>
  );
};

const ChatSidebar = ({ chatHistory, onSendMessage, isProcessingChat, zone, onGenerateEstimate }) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [chatHistory, isProcessingChat]);

  return (
    <div style={{ width: '400px', display: 'flex', flexDirection: 'column', backgroundColor: 'var(--background)' }}>
      <div style={{ padding: '24px', borderBottom: '1px solid var(--border)' }}>
        <h2 style={{ fontFamily: 'var(--font-display)', fontSize: '24px', margin: 0 }}>Co-Designer</h2>
        <p style={{ fontSize: '14px', color: 'var(--text-secondary)', margin: 0 }}>Spatial reasoning & zoning</p>
      </div>

      <div ref={scrollRef} style={{ flex: 1, overflowY: 'auto', padding: '24px', display: 'flex', flexDirection: 'column', gap: '24px' }}>
        {chatHistory.map((msg, i) => (
          <div key={i} style={{ 
            alignSelf: msg.role === 'user' ? 'flex-end' : 'flex-start',
            maxWidth: '85%',
            backgroundColor: msg.role === 'user' ? 'var(--surface)' : 'transparent',
            border: msg.role === 'user' ? '1px solid var(--border)' : 'none',
            padding: msg.role === 'user' ? '12px 16px' : '0',
            borderRadius: 'var(--radius)'
          }}>
            {msg.role === 'ai' && (
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px', color: 'var(--emphasis)' }}>
                <lucide.Sparkles size={16} />
                <span style={{ fontSize: '12px', fontWeight: 700, letterSpacing: '0.05em' }}>TERRAFLOW AI</span>
              </div>
            )}
            <div style={{ fontSize: '14px', lineHeight: 1.5, color: 'var(--text-primary)' }}>
              {msg.content}
            </div>
          </div>
        ))}
        {isProcessingChat && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--text-tertiary)' }}>
            <motion.div animate={{ rotate: 360 }} transition={{ duration: 2, repeat: Infinity, ease: "linear" }}>
              <lucide.Loader2 size={16} />
            </motion.div>
            <span style={{ fontSize: '14px' }}>Calculating spatial coordinates...</span>
          </div>
        )}
      </div>

      {zone && (
        <div style={{ padding: '24px', borderTop: '1px solid var(--border)', backgroundColor: 'var(--surface)' }}>
          <button 
            className="btn-primary" 
            style={{ width: '100%' }}
            onClick={onGenerateEstimate}
          >
            Generate Preliminary Estimate
          </button>
        </div>
      )}

      <div style={{ padding: '24px', borderTop: '1px solid var(--border)' }}>
        <form onSubmit={(e) => { e.preventDefault(); if(input.trim()) { onSendMessage(input); setInput(''); } }} style={{ display: 'flex', gap: '8px' }}>
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="e.g., Add a 15x15 patio in the sunniest spot..."
            disabled={isProcessingChat}
            style={{
              flex: 1,
              height: '44px',
              padding: '0 16px',
              border: '1px solid var(--border)',
              borderRadius: 'var(--radius)',
              fontFamily: 'var(--font-body)',
              fontSize: '14px',
              backgroundColor: 'var(--surface)',
              outline: 'none'
            }}
          />
          <button type="submit" className="btn-primary" disabled={isProcessingChat || !input.trim()} style={{ width: '44px', padding: 0, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
            <lucide.Send size={16} />
          </button>
        </form>
      </div>
    </div>
  );
};

const EstimatePanel = ({ estimate, onClose }) => {
  const total = estimate.reduce((sum, item) => sum + item.total, 0);

  return (
    <motion.div
      initial={{ x: '-100%', opacity: 0 }}
      animate={{ x: 0, opacity: 1 }}
      transition={{ type: 'spring', damping: 25, stiffness: 200 }}
      style={{
        position: 'absolute',
        top: 0, left: 0, bottom: 0,
        width: '450px',
        backgroundColor: 'var(--background)',
        borderRight: '1px solid var(--border)',
        boxShadow: '4px 0 24px rgba(0,0,0,0.05)',
        zIndex: 20,
        display: 'flex',
        flexDirection: 'column'
      }}
    >
      <div style={{ padding: '24px', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <h2 style={{ fontFamily: 'var(--font-display)', fontSize: '32px', margin: 0 }}>Preliminary Estimate</h2>
          <p style={{ fontSize: '14px', color: 'var(--text-secondary)', margin: 0 }}>Based on spatial zones & constraints</p>
        </div>
        <button className="btn-ghost" onClick={onClose} style={{ padding: '8px' }}><lucide.X size={20} /></button>
      </div>

      <div style={{ padding: '24px', backgroundColor: 'rgba(253, 142, 46, 0.1)', borderBottom: '1px solid var(--border)', display: 'flex', gap: '12px' }}>
        <lucide.AlertTriangle size={20} color="var(--warning)" style={{ flexShrink: 0 }} />
        <div style={{ fontSize: '14px', color: 'var(--text-primary)' }}>
          <strong>Constraint Warning:</strong> The requested patio zone overlaps a 5% slope. Grading labor has been automatically added to the estimate.
        </div>
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: '24px' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid var(--border)', textAlign: 'left', color: 'var(--text-secondary)' }}>
              <th style={{ paddingBottom: '12px', fontWeight: 400 }}>Item</th>
              <th style={{ paddingBottom: '12px', fontWeight: 400, textAlign: 'right' }}>Qty</th>
              <th style={{ paddingBottom: '12px', fontWeight: 400, textAlign: 'right' }}>Cost</th>
              <th style={{ paddingBottom: '12px', fontWeight: 400, textAlign: 'right' }}>Total</th>
            </tr>
          </thead>
          <tbody>
            {estimate.map((item, i) => (
              <tr key={i} style={{ borderBottom: '1px solid var(--border)' }}>
                <td style={{ padding: '16px 0', fontWeight: 700 }}>{item.item}</td>
                <td style={{ padding: '16px 0', textAlign: 'right', fontFamily: 'var(--font-mono)' }}>{item.quantity} {item.unit}</td>
                <td style={{ padding: '16px 0', textAlign: 'right', fontFamily: 'var(--font-mono)' }}>${item.unit_cost.toFixed(2)}</td>
                <td style={{ padding: '16px 0', textAlign: 'right', fontFamily: 'var(--font-mono)' }}>${item.total.toFixed(2)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div style={{ padding: '24px', borderTop: '1px solid var(--border)', backgroundColor: 'var(--surface)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
          <span style={{ fontSize: '16px', fontWeight: 700 }}>Estimated Total</span>
          <span style={{ fontFamily: 'var(--font-mono)', fontSize: '24px', fontWeight: 700, color: 'var(--emphasis)' }}>
            ${total.toFixed(2)}
          </span>
        </div>
        <button className="btn-primary" style={{ width: '100%' }}>Export Proposal</button>
      </div>
    </motion.div>
  );
};

// --- Main App ---

const App = () => {
  const [screen, setScreen] = useState('s1_project_dashboard');
  const [constraints, setConstraints] = useState([]);
  const [zone, setZone] = useState(null);
  const [estimate, setEstimate] = useState(null);
  const [chatHistory, setChatHistory] = useState([
    { role: 'ai', content: 'Site constraints extracted successfully. I found a 5% slope and a large shade zone. What would you like to design?' }
  ]);
  const [isProcessingChat, setIsProcessingChat] = useState(false);
  const [isEstimating, setIsEstimating] = useState(false);

  // Inject CSS Variables
  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=Archivo:wght@400;700&family=Bebas+Neue&family=JetBrains+Mono&display=swap');

      :root {
        --background: #FFFFFF;
        --surface: #FAFAFA;
        --panel: #F5F5F0;
        --text-primary: #0D0D0D;
        --text-secondary: #525252;
        --text-tertiary: #ACACAC;
        --border: #E5E5E5;
        --lime: #B8B800;
        --teal: #115054;
        --cyan: #00B7C3;
        --rust: #CC6644;
        --success: #0CCE6B;
        --warning: #FD8E2E;
        --friction: #CC6644;
        --opportunity: #B8B800;
        --emphasis: #B8B800;

        --font-display: 'Bebas Neue', sans-serif;
        --font-body: 'Archivo', sans-serif;
        --font-mono: 'JetBrains Mono', monospace;

        --radius: 2px;
        --btn-height: 44px;
      }

      body {
        margin: 0;
        font-family: var(--font-body);
        background-color: var(--background);
        color: var(--text-primary);
        -webkit-font-smoothing: antialiased;
      }

      button {
        height: var(--btn-height);
        border-radius: var(--radius);
        font-family: var(--font-body);
        font-weight: 700;
        font-size: 14px;
        cursor: pointer;
        transition: all 0.2s ease;
        border: none;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 8px;
        padding: 0 24px;
      }

      .btn-primary {
        background-color: var(--teal);
        color: #FFFFFF;
      }
      .btn-primary:hover:not(:disabled) {
        background-color: #0d3d40;
      }
      .btn-primary:disabled {
        opacity: 0.5;
        cursor: not-allowed;
      }

      .btn-ghost {
        background-color: transparent;
        color: var(--text-primary);
        border: 1px solid transparent;
      }
      .btn-ghost:hover {
        background-color: var(--surface);
        border-color: var(--border);
      }

      * { box-sizing: border-box; }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  const handleUpload = () => setScreen('s2_processing_synthesis');

  const handleVisionComplete = (extractedConstraints) => {
    setConstraints(extractedConstraints);
    setScreen('s3_workspace_base');
  };

  const handleSendMessage = async (msg) => {
    setChatHistory(prev => [...prev, { role: 'user', content: msg }]);
    setIsProcessingChat(true);

    try {
      const res = await fetch('/api/ai/anthropic', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-opus-4-6',
          max_tokens: 1000,
          messages: [
            { role: 'system', content: 'You are a spatial reasoning AI. Return ONLY valid JSON. Format: { "zone": { "name": "string", "coordinates": [[x,y]...], "area_sqft": number }, "chat_response": "string" }' },
            { role: 'user', content: `Constraints: ${JSON.stringify(constraints)}. User wants: ${msg}` }
          ]
        })
      });
      const data = await res.json();
      const parsed = parseAIJSON(data?.content?.[0]?.text || '');

      if (parsed && parsed.zone) {
        setZone(parsed.zone);
        setChatHistory(prev => [...prev, { role: 'ai', content: parsed.chat_response }]);
      } else {
        throw new Error("Invalid format");
      }
    } catch (e) {
      // Fallback if proxy fails
      setTimeout(() => {
        setZone(FALLBACK_ZONE);
        setChatHistory(prev => [...prev, { role: 'ai', content: FALLBACK_ZONE.ai_rationale }]);
      }, 1500);
    } finally {
      setIsProcessingChat(false);
      setScreen('s4_workspace_zoned');
    }
  };

  const handleGenerateEstimate = async () => {
    setIsEstimating(true);
    setScreen('s5_estimate_panel');

    try {
      const res = await fetch('/api/ai/openai', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
        body: JSON.stringify({
          model: 'gpt-5.5',
          messages: [
            { role: 'system', content: 'You are an estimator. Return ONLY valid JSON. Format: { "line_items": [ { "item": "string", "quantity": number, "unit": "string", "unit_cost": number, "total": number } ] }' },
            { role: 'user', content: `Zone: ${JSON.stringify(zone)}. Constraints: ${JSON.stringify(constraints)}.` }
          ],
          temperature: 0.2
        })
      });
      const data = await res.json();
      const parsed = parseAIJSON(data?.choices?.[0]?.message?.content || '');

      if (parsed && parsed.line_items) {
        setEstimate(parsed.line_items);
      } else {
        throw new Error("Invalid format");
      }
    } catch (e) {
      setTimeout(() => setEstimate(FALLBACK_ESTIMATE), 1000);
    } finally {
      setIsEstimating(false);
    }
  };

  const resetState = () => {
    setScreen('s1_project_dashboard');
    setConstraints([]);
    setZone(null);
    setEstimate(null);
    setChatHistory([{ role: 'ai', content: 'Site constraints extracted successfully. I found a 5% slope and a large shade zone. What would you like to design?' }]);
  };

  return (
    <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
      <Header onReset={resetState} />

      {/* Demo Controls */}
      <div style={{ position: 'absolute', top: '70px', right: '24px', zIndex: 100, display: 'flex', gap: '8px', backgroundColor: 'var(--surface)', padding: '8px', border: '1px solid var(--border)', borderRadius: 'var(--radius)' }}>
        <span style={{ fontSize: '10px', fontWeight: 'bold', alignSelf: 'center', marginRight: '8px' }}>DEMO:</span>
        {['s1', 's2', 's3', 's4', 's5'].map(s => (
          <button 
            key={s} 
            onClick={() => setScreen(s + (s==='s1'? '_project_dashboard' : s==='s2'? '_processing_synthesis' : s==='s3'? '_workspace_base' : s==='s4'? '_workspace_zoned' : '_estimate_panel'))}
            style={{ height: '24px', padding: '0 8px', fontSize: '10px', backgroundColor: screen.startsWith(s) ? 'var(--emphasis)' : 'transparent', color: screen.startsWith(s) ? '#000' : 'var(--text-secondary)' }}
          >
            {s.toUpperCase()}
          </button>
        ))}
      </div>

      <main style={{ flex: 1, display: 'flex', position: 'relative' }}>
        <AnimatePresence mode="wait">
          {screen === 's1_project_dashboard' && (
            <motion.div key="s1" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} style={{ width: '100%' }}>
              <Screen1_Dashboard onUpload={handleUpload} />
            </motion.div>
          )}

          {screen === 's2_processing_synthesis' && (
            <motion.div key="s2" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} style={{ width: '100%' }}>
              <Screen2_Processing onComplete={handleVisionComplete} />
            </motion.div>
          )}

          {(screen === 's3_workspace_base' || screen === 's4_workspace_zoned' || screen === 's5_estimate_panel') && (
            <motion.div key="workspace" initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ width: '100%', display: 'flex' }}>
              <MapViewport 
                constraints={constraints.length ? constraints : FALLBACK_CONSTRAINTS} 
                zone={screen !== 's3_workspace_base' ? (zone || FALLBACK_ZONE) : null} 
                isEstimating={screen === 's5_estimate_panel'}
              />
              <ChatSidebar 
                chatHistory={chatHistory} 
                onSendMessage={handleSendMessage} 
                isProcessingChat={isProcessingChat}
                zone={screen !== 's3_workspace_base' ? (zone || FALLBACK_ZONE) : null}
                onGenerateEstimate={handleGenerateEstimate}
              />

              <AnimatePresence>
                {screen === 's5_estimate_panel' && (
                  <EstimatePanel 
                    estimate={estimate || FALLBACK_ESTIMATE} 
                    onClose={() => setScreen('s4_workspace_zoned')} 
                  />
                )}
              </AnimatePresence>
            </motion.div>
          )}
        </AnimatePresence>
      </main>
    </div>
  );
};

