const MapViewport = ({ constraints, zone, isEstimating }) => {
  const [activeLayers, setActiveLayers] = useState({ shade: true, slope: true, structure: true });
  const [hoveredElement, setHoveredElement] = useState(null);

  const toSvgCoords = (coords) => coords.map(c => `${c[0]},${c[1]}`).join(' ');

  const toggleLayer = (layer) => {
    setActiveLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div style={{ 
      flex: 1, 
      backgroundColor: 'var(--background)', 
      position: 'relative',
      overflow: 'hidden',
      borderRight: '1px solid var(--border)',
      transition: 'all 0.5s ease',
      opacity: isEstimating ? 0.5 : 1
    }}>
      <div style={{ position: 'absolute', inset: 0, backgroundImage: 'linear-gradient(var(--border) 1px, transparent 1px), linear-gradient(90deg, var(--border) 1px, transparent 1px)', backgroundSize: '20px 20px', opacity: 0.2 }} />

      <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none" style={{ position: 'absolute', inset: 0 }}>
        {constraints.filter(c => activeLayers[c.type]).map(c => {
          let fill = 'rgba(255,255,255,0.02)';
          let stroke = 'var(--border)';
          if (c.type === 'shade') { fill = 'rgba(17, 80, 84, 0.3)'; stroke = 'var(--teal)'; }
          if (c.type === 'slope') { fill = 'rgba(204, 102, 68, 0.2)'; stroke = 'var(--friction)'; }

          const isHovered = hoveredElement === c.id;

          return (
            <g 
              key={c.id} 
              onMouseEnter={() => setHoveredElement(c.id)}
              onMouseLeave={() => setHoveredElement(null)}
              style={{ cursor: 'pointer', transition: 'all 0.2s' }}
            >
              <polygon 
                points={toSvgCoords(c.polygon_coordinates)} 
                fill={isHovered ? stroke : fill} 
                fillOpacity={isHovered ? 0.5 : 1}
                stroke={stroke} 
                strokeWidth={isHovered ? "1" : "0.5"}
                strokeDasharray={c.type === 'slope' ? "1,1" : "none"}
              />
              <text x={c.polygon_coordinates[0][0] + 2} y={c.polygon_coordinates[0][1] + 5} fontSize="2" fill="var(--text-secondary)" fontFamily="var(--font-mono)">
                {c.type.toUpperCase()}: {c.value}
              </text>
            </g>
          );
        })}

        <AnimatePresence>
          {zone && (
            <motion.g
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.5, ease: "easeOut" }}
              onMouseEnter={() => setHoveredElement(zone.id)}
              onMouseLeave={() => setHoveredElement(null)}
              style={{ cursor: 'pointer' }}
            >
              <polygon 
                points={toSvgCoords(zone.coordinates)} 
                fill={hoveredElement === zone.id ? "rgba(184, 184, 0, 0.5)" : "rgba(184, 184, 0, 0.3)"} 
                stroke="var(--emphasis)" 
                strokeWidth="1"
              />
              <text x={zone.coordinates[0][0] + 2} y={zone.coordinates[0][1] + 5} fontSize="3" fill="var(--text-primary)" fontFamily="var(--font-body)" fontWeight="bold">
                {zone.name}
              </text>
              <text x={zone.coordinates[0][0] + 2} y={zone.coordinates[0][1] + 8} fontSize="2" fill="var(--text-secondary)" fontFamily="var(--font-mono)">
                {zone.area_sqft} SQFT
              </text>
            </motion.g>
          )}
        </AnimatePresence>
      </svg>

      {hoveredElement && (
        <div style={{ position: 'absolute', top: '24px', left: '24px', backgroundColor: 'var(--surface)', padding: '12px', border: '1px solid var(--border)', borderRadius: 'var(--radius)', zIndex: 10 }}>
          <div style={{ fontSize: '12px', fontWeight: 700, color: 'var(--text-primary)' }}>
            {hoveredElement === zone?.id ? zone.name : constraints.find(c => c.id === hoveredElement)?.description}
          </div>
        </div>
      )}

      <div style={{ position: 'absolute', bottom: '24px', left: '24px', display: 'flex', gap: '8px', backgroundColor: 'var(--surface)', padding: '8px', border: '1px solid var(--border)', borderRadius: 'var(--radius)' }}>
        <div style={{ fontSize: '12px', fontWeight: 700, padding: '4px 8px', color: 'var(--text-secondary)' }}>LAYERS</div>
        <button 
          onClick={() => toggleLayer('shade')}
          style={{ fontSize: '12px', padding: '4px 8px', display: 'flex', alignItems: 'center', gap: '4px', backgroundColor: activeLayers.shade ? 'rgba(255,255,255,0.1)' : 'transparent', border: '1px solid transparent', borderColor: activeLayers.shade ? 'var(--border)' : 'transparent', height: 'auto' }}
        >
          <div style={{width:8,height:8,backgroundColor:'var(--teal)'}}/> Shade
        </button>
        <button 
          onClick={() => toggleLayer('slope')}
          style={{ fontSize: '12px', padding: '4px 8px', display: 'flex', alignItems: 'center', gap: '4px', backgroundColor: activeLayers.slope ? 'rgba(255,255,255,0.1)' : 'transparent', border: '1px solid transparent', borderColor: activeLayers.slope ? 'var(--border)' : 'transparent', height: 'auto' }}
        >
          <div style={{width:8,height:8,backgroundColor:'var(--friction)'}}/> Topography
        </button>
      </div>
    </div>
  );
};

const ChatSidebar = ({ chatHistory, onSendMessage, isProcessingChat, zone, onGenerateEstimate }) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [chatHistory, isProcessingChat]);

  return (
    <div style={{ width: '400px', display: 'flex', flexDirection: 'column', backgroundColor: 'var(--surface)', borderLeft: '1px solid var(--border)' }}>
      <div style={{ padding: '24px', borderBottom: '1px solid var(--border)' }}>
        <h2 style={{ fontFamily: 'var(--font-display)', fontSize: '24px', margin: 0 }}>Co-Designer</h2>
        <p style={{ fontSize: '14px', color: 'var(--text-secondary)', margin: 0 }}>Spatial reasoning & zoning</p>
      </div>

      <div ref={scrollRef} style={{ flex: 1, overflowY: 'auto', padding: '24px', display: 'flex', flexDirection: 'column', gap: '24px' }}>
        {chatHistory.map((msg, i) => (
          <div key={i} style={{ 
            alignSelf: msg.role === 'user' ? 'flex-end' : 'flex-start',
            maxWidth: '85%',
            backgroundColor: msg.role === 'user' ? 'rgba(255,255,255,0.05)' : 'transparent',
            border: msg.role === 'user' ? '1px solid var(--border)' : 'none',
            padding: msg.role === 'user' ? '12px 16px' : '0',
            borderRadius: 'var(--radius)'
          }}>
            {msg.role === 'ai' && (
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px', color: 'var(--emphasis)' }}>
                <lucide.Sparkles size={16} />
                <span style={{ fontSize: '12px', fontWeight: 700, letterSpacing: '0.05em' }}>TERRAFLOW AI</span>
              </div>
            )}
            <div style={{ fontSize: '14px', lineHeight: 1.5, color: 'var(--text-primary)' }}>
              {msg.content}
            </div>
          </div>
        ))}
        {isProcessingChat && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--text-secondary)' }}>
            <motion.div animate={{ rotate: 360 }} transition={{ duration: 2, repeat: Infinity, ease: "linear" }}>
              <lucide.Loader2 size={16} />
            </motion.div>
            <span style={{ fontSize: '14px' }}>Calculating spatial coordinates...</span>
          </div>
        )}
      </div>

      {zone && (
        <div style={{ padding: '24px', borderTop: '1px solid var(--border)', backgroundColor: 'var(--background)' }}>
          <button 
            className="btn-primary" 
            style={{ width: '100%' }}
            onClick={onGenerateEstimate}
          >
            Generate Preliminary Estimate
          </button>
        </div>
      )}

      <div style={{ padding: '24px', borderTop: '1px solid var(--border)', backgroundColor: 'var(--background)' }}>
        <form onSubmit={(e) => { e.preventDefault(); if(input.trim()) { onSendMessage(input); setInput(''); } }} style={{ display: 'flex', gap: '8px' }}>
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="e.g., Add a 15x15 patio in the sunniest spot..."
            disabled={isProcessingChat}
            style={{
              flex: 1,
              height: '44px',
              padding: '0 16px',
              border: '1px solid var(--border)',
              borderRadius: 'var(--radius)',
              fontFamily: 'var(--font-body)',
              fontSize: '14px',
              backgroundColor: 'var(--surface)',
              color: 'var(--text-primary)',
              outline: 'none'
            }}
          />
          <button type="submit" className="btn-primary" disabled={isProcessingChat || !input.trim()} style={{ width: '44px', padding: 0, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
            {isProcessingChat ? (
              <motion.div animate={{ rotate: 360 }} transition={{ duration: 2, repeat: Infinity, ease: "linear" }}>
                <lucide.Loader2 size={16} />
              </motion.div>
            ) : (
              <lucide.Send size={16} />
            )}
          </button>
        </form>
      </div>
    </div>
  );
};

const EstimatePanel = ({ estimate, onClose }) => {
  const total = estimate.reduce((sum, item) => sum + item.total, 0);

  return (
    <motion.div
      initial={{ x: '-100%', opacity: 0 }}
      animate={{ x: 0, opacity: 1 }}
      exit={{ x: '-100%', opacity: 0 }}
      transition={{ type: 'spring', damping: 25, stiffness: 200 }}
      style={{
        position: 'absolute',
        top: 0, left: 0, bottom: 0,
        width: '450px',
        backgroundColor: 'var(--surface)',
        borderRight: '1px solid var(--border)',
        boxShadow: '4px 0 24px rgba(0,0,0,0.5)',
        zIndex: 20,
        display: 'flex',
        flexDirection: 'column'
      }}
    >
      <div style={{ padding: '24px', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: 'var(--background)' }}>
        <div>
          <h2 style={{ fontFamily: 'var(--font-display)', fontSize: '32px', margin: 0 }}>Preliminary Estimate</h2>
          <p style={{ fontSize: '14px', color: 'var(--text-secondary)', margin: 0 }}>Based on spatial zones & constraints</p>
        </div>
        <button className="btn-ghost" onClick={onClose} style={{ padding: '8px', height: 'auto' }}><lucide.X size={20} /></button>
      </div>

      <div style={{ padding: '24px', backgroundColor: 'rgba(253, 142, 46, 0.1)', borderBottom: '1px solid var(--border)', display: 'flex', gap: '12px' }}>
        <lucide.AlertTriangle size={20} color="var(--warning)" style={{ flexShrink: 0 }} />
        <div style={{ fontSize: '14px', color: 'var(--text-primary)' }}>
          <strong>Constraint Warning:</strong> The requested patio zone overlaps a 5% slope. Grading labor has been automatically added to the estimate.
        </div>
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: '24px' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid var(--border)', textAlign: 'left', color: 'var(--text-secondary)' }}>
              <th style={{ paddingBottom: '12px', fontWeight: 400 }}>Item</th>
              <th style={{ paddingBottom: '12px', fontWeight: 400, textAlign: 'right' }}>Qty</th>
              <th style={{ paddingBottom: '12px', fontWeight: 400, textAlign: 'right' }}>Cost</th>
              <th style={{ paddingBottom: '12px', fontWeight: 400, textAlign: 'right' }}>Total</th>
            </tr>
          </thead>
          <tbody>
            {estimate.map((item, i) => (
              <tr key={i} style={{ borderBottom: '1px solid var(--border)' }}>
                <td style={{ padding: '16px 0', fontWeight: 700 }}>{item.item}</td>
                <td style={{ padding: '16px 0', textAlign: 'right', fontFamily: 'var(--font-mono)' }}>{item.quantity} {item.unit}</td>
                <td style={{ padding: '16px 0', textAlign: 'right', fontFamily: 'var(--font-mono)' }}>${item.unit_cost.toFixed(2)}</td>
                <td style={{ padding: '16px 0', textAlign: 'right', fontFamily: 'var(--font-mono)' }}>${item.total.toFixed(2)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div style={{ padding: '24px', borderTop: '1px solid var(--border)', backgroundColor: 'var(--background)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
          <span style={{ fontSize: '16px', fontWeight: 700 }}>Estimated Total</span>
          <span style={{ fontFamily: 'var(--font-mono)', fontSize: '24px', fontWeight: 700, color: 'var(--emphasis)' }}>
            ${total.toFixed(2)}
          </span>
        </div>
        <button className="btn-primary" style={{ width: '100%' }}>Export Proposal</button>
      </div>
    </motion.div>
  );
};

// --- Main App ---

const App = () => {
  const [screen, setScreen] = useState('s1_project_dashboard');
  const [constraints, setConstraints] = useState([]);
  const [zone, setZone] = useState(null);
  const [estimate, setEstimate] = useState(null);
  const [chatHistory, setChatHistory] = useState([
    { role: 'ai', content: 'Site constraints extracted successfully. I found a 5% slope and a large shade zone. What would you like to design?' }
  ]);
  const [isProcessingChat, setIsProcessingChat] = useState(false);
  const [isEstimating, setIsEstimating] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  // Inject CSS Variables for Dark Mode based strictly on DS hexes
  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=Archivo:wght@400;700&family=Bebas+Neue&family=JetBrains+Mono&display=swap');

      :root {
        --background: #0D0D0D;
        --surface: #0D0D0D;
        --text-primary: #FFFFFF;
        --text-secondary: #FAFAFA;
        --border: #525252;
        --teal: #115054;
        --cyan: #00B7C3;
        --success: #0CCE6B;
        --warning: #FD8E2E;
        --friction: #CC6644;
        --opportunity: #B8B800;
        --emphasis: #B8B800;

        --font-display: 'Bebas Neue', sans-serif;
        --font-body: 'Archivo', sans-serif;
        --font-mono: 'JetBrains Mono', monospace;

        --radius: 2px;
        --btn-height: 44px;
      }

      body {
        margin: 0;
        font-family: var(--font-body);
        background-color: var(--background);
        color: var(--text-primary);
        -webkit-font-smoothing: antialiased;
      }

      button {
        height: var(--btn-height);
        border-radius: var(--radius);
        font-family: var(--font-body);
        font-weight: 700;
        font-size: 14px;
        cursor: pointer;
        transition: all 0.2s ease;
        border: none;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 8px;
        padding: 0 24px;
      }

      .btn-primary {
        background-color: var(--teal);
        color: #FFFFFF;
      }
      .btn-primary:hover:not(:disabled) {
        opacity: 0.9;
      }
      .btn-primary:disabled {
        opacity: 0.5;
        cursor: not-allowed;
      }

      .btn-ghost {
        background-color: transparent;
        color: var(--text-primary);
        border: 1px solid transparent;
      }
      .btn-ghost:hover {
        background-color: rgba(255,255,255,0.05);
        border-color: var(--border);
      }

      * { box-sizing: border-box; }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  const handleUpload = () => setScreen('s2_processing_synthesis');

  const handleVisionComplete = (extractedConstraints) => {
    setConstraints(extractedConstraints);
    setScreen('s3_workspace_base');
  };

  const handleSendMessage = async (msg) => {
    setChatHistory(prev => [...prev, { role: 'user', content: msg }]);
    setIsProcessingChat(true);

    try {
      const res = await fetch('/api/ai/anthropic', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-3-5-sonnet-20240620',
          max_tokens: 1000,
          messages: [
            { role: 'system', content: 'You are a spatial reasoning AI. Return ONLY valid JSON. Format: { "zone": { "name": "string", "coordinates": [[x,y]...], "area_sqft": number }, "chat_response": "string" }' },
            { role: 'user', content: `Constraints: ${JSON.stringify(constraints)}. User wants: ${msg}` }
          ]
        })
      });
      const data = await res.json();
      const parsed = parseAIJSON(data?.content?.[0]?.text || '');

      if (parsed && parsed.zone) {
        setZone(parsed.zone);
        setChatHistory(prev => [...prev, { role: 'ai', content: parsed.chat_response }]);
      } else {
        throw new Error("Invalid format");
      }
    } catch (e) {
      setTimeout(() => {
        setZone(FALLBACK_ZONE);
        setChatHistory(prev => [...prev, { role: 'ai', content: FALLBACK_ZONE.ai_rationale }]);
      }, 1500);
    } finally {
      setIsProcessingChat(false);
      setScreen('s4_workspace_zoned');
    }
  };

  const handleGenerateEstimate = async () => {
    setIsEstimating(true);
    setScreen('s5_estimate_panel');

    try {
      const res = await fetch('/api/ai/openai', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
        body: JSON.stringify({
          model: 'gpt-4o',
          messages: [
            { role: 'system', content: 'You are an estimator. Return ONLY valid JSON. Format: { "line_items": [ { "item": "string", "quantity": number, "unit": "string", "unit_cost": number, "total": number } ] }' },
            { role: 'user', content: `Zone: ${JSON.stringify(zone)}. Constraints: ${JSON.stringify(constraints)}.` }
          ],
          temperature: 0.2
        })
      });
      const data = await res.json();
      const parsed = parseAIJSON(data?.choices?.[0]?.message?.content || '');

      if (parsed && parsed.line_items) {
        setEstimate(parsed.line_items);
      } else {
        throw new Error("Invalid format");
      }
    } catch (e) {
      setTimeout(() => setEstimate(FALLBACK_ESTIMATE), 1000);
    } finally {
      setIsEstimating(false);
    }
  };

  const resetState = () => {
    setScreen('s1_project_dashboard');
    setConstraints([]);
    setZone(null);
    setEstimate(null);
    setChatHistory([{ role: 'ai', content: 'Site constraints extracted successfully. I found a 5% slope and a large shade zone. What would you like to design?' }]);
  };

  return (
    <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
      <Header onReset={resetState} onToggleSettings={() => setShowSettings(!showSettings)} />
      <SettingsPanel isOpen={showSettings} onClose={() => setShowSettings(false)} />

      <div style={{ position: 'absolute', top: '70px', right: '24px', zIndex: 100, display: 'flex', gap: '8px', backgroundColor: 'var(--surface)', padding: '8px', border: '1px solid var(--border)', borderRadius: 'var(--radius)' }}>
        <span style={{ fontSize: '10px', fontWeight: 'bold', alignSelf: 'center', marginRight: '8px', color: 'var(--text-secondary)' }}>DEMO:</span>
        {['s1', 's2', 's3', 's4', 's5'].map(s => (
          <button 
            key={s} 
            onClick={() => setScreen(s + (s==='s1'? '_project_dashboard' : s==='s2'? '_processing_synthesis' : s==='s3'? '_workspace_base' : s==='s4'? '_workspace_zoned' : '_estimate_panel'))}
            style={{ height: '24px', padding: '0 8px', fontSize: '10px', backgroundColor: screen.startsWith(s) ? 'var(--emphasis)' : 'transparent', color: screen.startsWith(s) ? '#000' : 'var(--text-secondary)' }}
          >
            {s.toUpperCase()}
          </button>
        ))}
      </div>

      <main style={{ flex: 1, display: 'flex', position: 'relative' }}>
        <AnimatePresence mode="wait">
          {screen === 's1_project_dashboard' && (
            <motion.div key="s1" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} style={{ width: '100%', display: 'flex' }}>
              <Screen1_Dashboard onUpload={handleUpload} />
            </motion.div>
          )}

          {screen === 's2_processing_synthesis' && (
            <motion.div key="s2" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} style={{ width: '100%', display: 'flex' }}>
              <Screen2_Processing onComplete={handleVisionComplete} />
            </motion.div>
          )}

          {(screen === 's3_workspace_base' || screen === 's4_workspace_zoned' || screen === 's5_estimate_panel') && (
            <motion.div key="workspace" initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ width: '100%', display: 'flex' }}>
              <MapViewport 
                constraints={constraints.length ? constraints : FALLBACK_CONSTRAINTS} 
                zone={screen !== 's3_workspace_base' ? (zone || FALLBACK_ZONE) : null} 
                isEstimating={screen === 's5_estimate_panel'}
              />
              <ChatSidebar 
                chatHistory={chatHistory} 
                onSendMessage={handleSendMessage} 
                isProcessingChat={isProcessingChat}
                zone={screen !== 's3_workspace_base' ? (zone || FALLBACK_ZONE) : null}
                onGenerateEstimate={handleGenerateEstimate}
              />

              <AnimatePresence>
                {screen === 's5_estimate_panel' && (
                  <EstimatePanel 
                    estimate={estimate || FALLBACK_ESTIMATE} 
                    onClose={() => setScreen('s4_workspace_zoned')} 
                  />
                )}
              </AnimatePresence>
            </motion.div>
          )}
        </AnimatePresence>
      </main>
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
